def _nodehome_staged_route_tests(repo_root, B, N, changed_paths, tree, vault_rel):
    """額外測試路由只讀捕獲樹及既有起點;不改正式檢查、安家或測試名判定。"""
    changes = _nodehome_changes(repo_root, B.where, tree)
    listing = _nodehome_list(repo_root, tree)
    if changes is None or listing is None:
        return set()
    changed_paths = {p for _c, old_path, new_path in changes for p in (old_path, new_path) if p}
    files, all_paths = listing
    layouts = (_nodehome_layout(B.all_paths), _nodehome_layout(all_paths))
    old = {_nodehome_key(value) for note in B.notes.values() for value in note["about"]}
    live = {_nodehome_key(value) for note in N.notes.values() for value in note["about"]}
    possible = {p for p in changed_paths & (old | live) if any(_nodehome_is_test(p, view) for view in layouts)}
    notes = [rel for rel, note in N.notes.items() if possible & {_nodehome_key(x) for x in note["about"]}]
    import time as _t
    blobs = _nodehome_cat_blobs_capped(repo_root, [f"{tree}:{vault_rel}/{rel}" for rel in notes],
                                      256 * 1024, timeout=5, max_total_bytes=8 * 1024 * 1024,
                                      deadline=_t.monotonic() + 5)
    if blobs is None:
        return set()
    captured_by_note = {rel: {_nodehome_key(value) for value in _nodehome_parse_note(raw)["about"]}
                        for rel, raw in zip(notes, blobs) if raw is not None}
    untrusted = set()
    for rel in notes:
        claimed = {_nodehome_key(value) for value in N.notes[rel]["about"]} & possible
        previous = {_nodehome_key(value) for value in B.notes.get(rel, {}).get("about", [])}
        untrusted.update(claimed - previous - captured_by_note.get(rel, set()))
    captured = {key for values in captured_by_note.values() for key in values}
    # 另一篇合法安家不能替本篇的途中假宣告作證;不确定时只撤回補助路由。
    candidates = (possible & (old | captured)) - untrusted
    read = _nodehome_reader(repo_root, tree, from_git=True)
    config = read(".lumos/config.json")
    if config is None and ".lumos/config.json" in all_paths:
        return set()
    cfg = _nodehome_config(repo_root, config, from_snapshot=True)
    skip = frozenset() if _is_toolchain_repo(repo_root) else _vendored_state(repo_root, tree)[0]
    routes = _nodehome_route_tests(repo_root, files, all_paths, candidates, tree, cfg, skip, reader=read)
    old_read = _nodehome_reader(repo_root, B.where, from_git=True)
    old_config = old_read(".lumos/config.json")
    if old_config is not None or ".lumos/config.json" not in B.all_paths:
        old_cfg = _nodehome_config(repo_root, old_config, from_snapshot=True)
        old_skip = frozenset() if B.where is None or _is_toolchain_repo(repo_root) else _vendored_state(repo_root, B.where)[0]
        routes.update(_nodehome_route_tests(repo_root, B.files, B.all_paths, candidates, B.where, old_cfg, old_skip,
                                           reader=old_read))
    return routes


def _nodehome_group_route_tests(repo_root, group, notes, route_cache, cfg, skip):
    """讀取層收集同提交測試證據;共享最近兩版完整清單,讀不到就撤回額外證據。"""
    candidates = {p for info in notes.values() for p in group["paths"] & info["own"]}
    routes = set()
    if not candidates:
        return routes
    for sha in [*group["parents"], group["sha"]]:
        if sha in route_cache:
            cached = route_cache.pop(sha)
        else:
            if len(route_cache) >= 2:
                route_cache.pop(next(iter(route_cache)))
            cached = (_nodehome_list(repo_root, sha), {}, _nodehome_reader(repo_root, sha, from_git=True))
        route_cache[sha] = cached
        lst, shebang, read = cached
        if lst is None:
            return set()
        files, all_paths = lst
        routes.update(_nodehome_route_tests(
            repo_root, files, all_paths, candidates, sha, cfg, skip, reader=read, shebang=shebang))
    return routes


def _nodehome_mark_note_content(repo_root, groups, vault_rel, tag_judge=None, route_cfg=None, route_skip=frozenset()):
    """推送前逐提交看寫回:每個提交裡,哪幾篇 Systems 節點的內容(摘要、決策、正文)是在這個提交改的——只補驗證連結、
    計劃連結這類簿記欄位的不算——以及那篇在這個提交前後管哪些檔。在讀取這一層先算好放進分組的 content_notes
    {這個提交之後的路徑: {type, status, own}},判定那層只在同一個提交裡比「管的檔」跟「改的程式」,不必跨提交追名字
    (合併進來的平行分支、一次推送改名好幾次都不影響——代碼審 r2 單reviewer)。這個提交裡改名的,拿改名前的路徑去
    上一個提交讀;這個提交才新開的算有變;讀不到一律當有變,照原本那樣查。"""
    pre = vault_rel + "/Systems/"
    route_cache = {}                                         # 至多兩版清單;父版先讀,線性相鄰提交可共用
    for g in groups or ():
        after = _nodehome_reader(repo_root, g["sha"])
        # 上一版用「這個提交的第幾個上一版」讀(sha^1、sha^2):跟起點那一側的讀取分開算,不跟它搶共用
        befores = [_nodehome_reader(repo_root, f"{g['sha']}^{i + 1}") for i in range(len(g["parents"]))]
        notes = {}
        for p in g["paths"]:
            if not (p.startswith(pre) and p.endswith(".md")) or p in g["gone"]:
                continue
            new = after(p)
            n = _nodehome_parse_note(new) if new is not None else None
            olds = [b(g["src"].get(p, p)) for b in befores]
            olds = [_nodehome_parse_note(o) for o in olds if o is not None]
            if n is not None and any(o["sig"] == n["sig"] or _nodehome_tag_only_change(o, n, tag_judge) for o in olds):
                continue                                    # 跟上一版一樣(只補簿記;合併時照搬某一邊也算):不算這個提交寫回
            own, statuses = set(), set()
            for x in [n] + olds:
                if x is not None:
                    own |= {k for k in (_nodehome_key(v) for v in x["about"]) if k}
                    statuses.add(x["status"])
            # 狀態看這個提交前後兩版(代碼審 r3 單reviewer:只看之後的,「這個提交降成 planned 順便寫、下一個再升回來」就繞過了)
            notes[p] = {"type": n["type"] if n else "system", "statuses": statuses or {"doing"}, "own": own}
        g["content_notes"] = notes
        if route_cfg is not None:
            g["route_tests"] = _nodehome_group_route_tests(repo_root, g, notes, route_cache, route_cfg, route_skip)
    return groups


